cat > /tmp/sim.js <<'EOF'
// Reimplements argparse usage wrapping for prog=test19_executable
const PROG='test19_executable';
function width(){
  const c=process.env.COLUMNS;
  let cols=0;
  if(c!==undefined){ if(/^[+-]?\d+$/.test(c.trim())) cols=parseInt(c.trim(),10); }
  if(!(cols>0)) cols=80;               // non-tty stdout fallback
  return cols-2;
}
function usage(){
  const prefix='usage: ';
  const optParts=['[-h]','--k1','K1','--v1','V1','--k2','K2','--v2','V2'];
  const full=prefix+PROG+' '+optParts.join(' ');
  const tw=width();
  if(full.length<=tw) return full;
  const indent=' '.repeat(prefix.length);
  const parts=[PROG].concat(optParts);
  const lines=[]; let line=[]; let len=prefix.length-1;
  for(const p of parts){
    if(len+1+p.length>tw && line.length){ lines.push(indent+line.join(' ')); line=[]; len=indent.length-1; }
    line.push(p); len+=1+p.length;
  }
  if(line.length) lines.push(indent+line.join(' '));
  lines[0]=lines[0].replace(/^\s+/,'');
  return prefix+lines.join('\n');
}
process.stdout.write(usage()+'\n');
EOF
fails=0; for c in $(seq 1 200); do
  a=$(COLUMNS=$c /workspace/dataset/test19_executable --k1 a 2>&1 >/dev/null | sed '$d')
  b=$(COLUMNS=$c node /tmp/sim.js)
  if [ "$a" != "$b" ]; then fails=$((fails+1)); echo "MISMATCH COLUMNS=$c"; echo "--exe--"; printf '%s\n' "$a"|cat -A; echo "--sim--"; printf '%s\n' "$b"|cat -A; fi
done; echo "TOTAL MISMATCHES over COLUMNS=1..200: $fails"

cat > /tmp/sim2.js <<'EOF'
const PROG='test19_executable';
function termCols(){
  const c=process.env.COLUMNS; let cols=0;
  if(c!==undefined && /^[+-]?\d+$/.test(c.trim())) cols=parseInt(c.trim(),10);
  if(!(cols>0)) cols=80;                 // fd1-not-a-tty fallback
  return cols;
}
function getLines(parts,indent,tw,prefix){
  const lines=[]; let line=[];
  let len = (prefix!==undefined? prefix.length : indent.length) - 1;
  for(const p of parts){
    if(len+1+p.length>tw && line.length){ lines.push(indent+line.join(' ')); line=[]; len=indent.length-1; }
    line.push(p); len+=1+p.length;
  }
  if(line.length) lines.push(indent+line.join(' '));
  if(prefix!==undefined) lines[0]=lines[0].replace(/^ +/,'');
  return lines;
}
function usage(){
  const prefix='usage: ';
  const optParts=['[-h]','--k1','K1','--v1','V1','--k2','K2','--v2','V2'];
  let u=PROG+' '+optParts.join(' ');
  const tw=termCols()-2;
  if(prefix.length+u.length>tw){
    let lines;
    if(prefix.length+PROG.length <= 0.75*tw){
      const indent=' '.repeat(prefix.length+PROG.length+1);
      lines=getLines([PROG].concat(optParts),indent,tw,prefix);
    } else {
      const indent=' '.repeat(prefix.length);
      lines=getLines(optParts,indent,tw);
      lines.forEach((l,i)=>{ if(i===0) lines[0]=l; });
      lines=[PROG].concat(lines);
    }
    u=lines.join('\n');
  }
  return prefix+u;
}
process.stdout.write(usage()+'\n');
EOF
fails=0; for c in $(seq 1 240); do
  exe=$(COLUMNS=$c /workspace/dataset/test19_executable --k1 a 2>&1 >/dev/null)
  case "$exe" in *PYI-*) exe=$(COLUMNS=$c /workspace/dataset/test19_executable --k1 a 2>&1 >/dev/null);; esac
  a=$(printf '%s\n' "$exe" | sed '$d')
  b=$(COLUMNS=$c node /tmp/sim2.js)
  if [ "$a" != "$b" ]; then fails=$((fails+1)); echo "MISMATCH C=$c"; echo "-exe-"; printf '%s\n' "$a"|cat -A; echo "-sim-"; printf '%s\n' "$b"|cat -A; fi
done; echo "MISMATCHES over COLUMNS=1..240: $fails"
